+	const result: ParsedStatus = {
+		branch: null,
+		hasUpstream: false,
+		ahead: 0,
+		behind: 0,
+		staged: [],
+		unstaged: [],
+		untracked: [],
+	};
+	const records = output.split("\0");
+	for (let index = 0; index < records.length; index++) {
+		const record = records[index];
+		if (!record) continue;
+		if (record.startsWith("## ")) {
