+async function commitBase(git: GitRunner, sha: string): Promise<string> {
+	return git(["rev-parse", "--verify", "--quiet", `${sha}^`]).then(
+		(parent) => parent.trim() || EMPTY_TREE,
+		() => EMPTY_TREE,
+	);
