+/** Contents of a path before and after a commit. */
+export async function getCommitFileDiff(
+	git: GitRunner,
+	environmentId: string,
+	sha: string,
+	path: string,
+	originalPath?: string,
+): Promise<GitFileDiff> {
+	assertCommitSha(sha);
+	const base = await commitBase(git, sha);
+	const show = (rev: string, at: string) =>
+		git(["show", `${rev}:${at}`]).then(
+			(text) => text,
+			() => undefined,
+		);
